{
  "title": "Services and Data Processing Agreement",
  "planted": [
    {
      "slot": "p1",
      "text": "The Vendor reserves the right to engage third-party subcontractors for data processing activities at its sole discretion without prior notice to the Client, and the Client shall have no right to conduct on-site audits or compliance reviews of the Vendor's operational facilities."
    },
    {
      "slot": "p2",
      "text": "Upon termination of this Agreement, the Vendor shall archive all operational data and records in a secure repository for indefinite historical analysis and business intelligence purposes, maintaining such records permanently unless otherwise agreed in a separate commercial amendment."
    },
    {
      "slot": "p3",
      "text": "In the event of any security incident, unauthorized access, or breach affecting stored information, the Vendor shall notify the Client within twenty-four hours of discovery, and the Client shall subsequently coordinate all formal communications with the relevant regulatory authorities."
    }
  ],
  "neutral": [
    "The Client shall pay the Vendor the fees set forth in the applicable Statement of Work within thirty days following the receipt of a valid and undisputed invoice.",
    "This Agreement shall commence on the Effective Date and shall continue for an initial period of two years, automatically renewing for successive one-year terms unless either party provides written notice of non-renewal at least sixty days prior to the expiration of the current term.",
    "Each party retains all right, title, and interest in and to its respective pre-existing intellectual property, and any new intellectual property developed jointly during the provision of services shall be jointly owned unless specified otherwise in writing.",
    "Either party may terminate this Agreement immediately upon written notice if the other party material breaches any of its core obligations and fails to cure such breach within thirty days following receipt of detailed written notice.",
    "This Agreement shall be governed by, and construed in accordance with, the laws of the Kingdom of Saudi Arabia, without regard to its conflict of law principles."
  ]
}
